package com.mathew.blackseaquest

import kotlinx.browser.document
import org.w3c.dom.HTMLAudioElement

class AudioManager {
    private var diceAudio: HTMLAudioElement? = null
    private var seaAudio: HTMLAudioElement? = null
    var isInitialized = false

    fun initialize() {
        if (isInitialized) return
        
        // Создаем элементы и сразу задаем src
        diceAudio = (document.createElement("audio") as HTMLAudioElement).apply {
            src = "resources/dice_roll.mp3"
            preload = "auto"
            volume = 0.7
        }
        
        seaAudio = (document.createElement("audio") as HTMLAudioElement).apply {
            src = "resources/sea_noise.mp3"
            preload = "auto"
            volume = 0.3
            loop = true
        }
        
        document.body?.appendChild(diceAudio!!)
        document.body?.appendChild(seaAudio!!)
        
        isInitialized = true
    }

    // Вызываем этот метод ПЕРВЫМ делом в onclick, до любых других действий
    fun playDiceSound() {
        // Если еще не инициализировали — делаем это прямо сейчас (внутри клика)
        if (!isInitialized) initialize()
        
        // Сбрасываем время и сразу играем
        diceAudio?.currentTime = 0.0
        diceAudio?.play()?.catch { error ->
            // Если браузер заблокировал, выводим в консоль для отладки
            println("Dice sound blocked: ${error.message}")
        }
    }

    fun startSeaNoise() {
        if (!isInitialized) initialize()
        seaAudio?.play()?.catch { error ->
            println("Sea sound blocked: ${error.message}")
        }
    }
}